begin;
create extension if not exists pgtap with schema extensions;
set local search_path = extensions, public, pg_temp;
select no_plan();

-- ---------------------------------------------------------------------------
-- Shape, security and privilege closure (PD-022 / ADR-0018).
-- ---------------------------------------------------------------------------
select has_function('public', 'get_tenant_person_direct_report_aggregate_v1', array['uuid', 'uuid']);
select is(
  (select prosecdef from pg_proc where oid = 'public.get_tenant_person_direct_report_aggregate_v1(uuid,uuid)'::regprocedure),
  true, 'aggregate boundary is SECURITY DEFINER');
select is(
  (select proconfig from pg_proc where oid = 'public.get_tenant_person_direct_report_aggregate_v1(uuid,uuid)'::regprocedure),
  array['search_path=public, pg_temp'], 'aggregate boundary search_path is hardened');
select function_privs_are(
  'public', 'get_tenant_person_direct_report_aggregate_v1', array['uuid', 'uuid'],
  'authenticated', array['EXECUTE'], 'authenticated alone can execute the aggregate boundary');
select function_privs_are(
  'public', 'get_tenant_person_direct_report_aggregate_v1', array['uuid', 'uuid'],
  'anon', array[]::text[], 'anon cannot execute the aggregate boundary');
select function_privs_are(
  'public', 'get_tenant_person_direct_report_aggregate_v1', array['uuid', 'uuid'],
  'public', array[]::text[], 'PUBLIC cannot execute the aggregate boundary');
select function_privs_are(
  'public', 'get_tenant_person_direct_report_aggregate_v1', array['uuid', 'uuid'],
  'service_role', array[]::text[], 'service_role is not an application path');

-- Minimized public contract: exactly these columns; NO respondent_count,
-- response_id, evaluator_id, timestamps, status, raw_score, min/max, order.
select is(
  (select proargnames from pg_proc where oid = 'public.get_tenant_person_direct_report_aggregate_v1(uuid,uuid)'::regprocedure),
  array[
    'p_company_id', 'p_person_id',
    'cycle_id', 'cycle_name', 'model_name', 'cycle_date',
    'aggregate_score', 'is_qualitative', 'suppressed'
  ]::text[],
  'aggregate boundary exposes only the minimized anonymous contract');
select ok(
  (select proargnames from pg_proc where oid = 'public.get_tenant_person_direct_report_aggregate_v1(uuid,uuid)'::regprocedure)
    @> array['aggregate_score']::text[]
  and not (
    (select proargnames from pg_proc where oid = 'public.get_tenant_person_direct_report_aggregate_v1(uuid,uuid)'::regprocedure)
    && array['respondent_count','response_id','evaluator_id','submitted_at','completed_at','response_status','raw_score']::text[]
  ),
  'no cardinality/response/evaluator/timestamp/status/raw_score in the public contract');

-- Scorer reuse (no duplicated formula) + private scorer stays closed.
select ok(
  (select prosrc from pg_proc where oid = 'public.get_tenant_person_direct_report_aggregate_v1(uuid,uuid)'::regprocedure)
    ~ 'compute_assessment_scored_result_v1',
  'aggregate boundary reuses the canonical scoring authority');
select function_privs_are(
  'public', 'compute_assessment_scored_result_v1', array['uuid', 'uuid'],
  'authenticated', array[]::text[], 'private scorer remains closed to authenticated');

