-- ---------------------------------------------------------------------------
-- Behaviour as owner (same-tenant, authorized).
-- ---------------------------------------------------------------------------
set local role authenticated;
select set_config('request.jwt.claims', '{"sub":"c3000000-0000-4000-8000-000000000001","role":"authenticated"}', true);

-- k threshold: 3 → suppressed, no score.
select is(
  (select suppressed from public.get_tenant_person_direct_report_aggregate_v1('c3000000-0000-4000-8000-000000000101','c3000000-0000-4000-8000-000000000205') where cycle_id = 'c3000000-0000-4000-8000-000000000401'),
  true, 'below k (3 eligible) the cycle is suppressed');
select is(
  (select aggregate_score from public.get_tenant_person_direct_report_aggregate_v1('c3000000-0000-4000-8000-000000000101','c3000000-0000-4000-8000-000000000205') where cycle_id = 'c3000000-0000-4000-8000-000000000401'),
  null::numeric, 'suppressed cycle exposes no score');
-- k threshold: 4 → aggregate available.
select is(
  (select suppressed from public.get_tenant_person_direct_report_aggregate_v1('c3000000-0000-4000-8000-000000000101','c3000000-0000-4000-8000-000000000205') where cycle_id = 'c3000000-0000-4000-8000-000000000402'),
  false, 'at k (4 eligible) the cycle is not suppressed');
select is(
  (select aggregate_score from public.get_tenant_person_direct_report_aggregate_v1('c3000000-0000-4000-8000-000000000101','c3000000-0000-4000-8000-000000000205') where cycle_id = 'c3000000-0000-4000-8000-000000000402'),
  80::numeric, 'four scores of 80 aggregate to 80');
select is(
  (select is_qualitative from public.get_tenant_person_direct_report_aggregate_v1('c3000000-0000-4000-8000-000000000101','c3000000-0000-4000-8000-000000000205') where cycle_id = 'c3000000-0000-4000-8000-000000000402'),
  false, 'quantitative cohort is not qualitative');
-- real averaging: 0,100,50,50 → 50.
select is(
  (select aggregate_score from public.get_tenant_person_direct_report_aggregate_v1('c3000000-0000-4000-8000-000000000101','c3000000-0000-4000-8000-000000000205') where cycle_id = 'c3000000-0000-4000-8000-000000000403'),
  50::numeric, 'aggregate is the mean of eligible overall scores (0/100/50/50 = 50)');
-- qualitative: eligible >= k but none scored → qualitative, no number.
select is(
  (select is_qualitative from public.get_tenant_person_direct_report_aggregate_v1('c3000000-0000-4000-8000-000000000101','c3000000-0000-4000-8000-000000000205') where cycle_id = 'c3000000-0000-4000-8000-000000000404'),
  true, 'a cohort with no quantitative scores is qualitative');
select is(
  (select aggregate_score from public.get_tenant_person_direct_report_aggregate_v1('c3000000-0000-4000-8000-000000000101','c3000000-0000-4000-8000-000000000205') where cycle_id = 'c3000000-0000-4000-8000-000000000404'),
  null::numeric, 'qualitative cohort emits no number and NULL is never zero');
select is(
  (select suppressed from public.get_tenant_person_direct_report_aggregate_v1('c3000000-0000-4000-8000-000000000101','c3000000-0000-4000-8000-000000000205') where cycle_id = 'c3000000-0000-4000-8000-000000000404'),
  false, 'a >= k qualitative cohort is shown (not suppressed)');
-- visibility none: fully excluded, not even suppressed.
select is(
  (select count(*) from public.get_tenant_person_direct_report_aggregate_v1('c3000000-0000-4000-8000-000000000101','c3000000-0000-4000-8000-000000000205') where cycle_id = 'c3000000-0000-4000-8000-000000000405'),
  0::bigint, 'visibility=none does not participate in the aggregate nor the cardinality');
-- cross-cycle: 2 + 2 never sum to k; both suppressed, no aggregate ever.
select is(
  (select count(*) from public.get_tenant_person_direct_report_aggregate_v1('c3000000-0000-4000-8000-000000000101','c3000000-0000-4000-8000-000000000209') where suppressed = false),
  0::bigint, 'cycles are never combined to reach k');
select is(
  (select count(*) from public.get_tenant_person_direct_report_aggregate_v1('c3000000-0000-4000-8000-000000000101','c3000000-0000-4000-8000-000000000209') where suppressed = true),
  2::bigint, 'each sub-threshold cycle is an independent suppressed anonymity set');
-- no results.
select is(
  (select count(*) from public.get_tenant_person_direct_report_aggregate_v1('c3000000-0000-4000-8000-000000000101','c3000000-0000-4000-8000-000000000206')),
  0::bigint, 'a Person with no direct-report Responses returns nothing');

-- ---------------------------------------------------------------------------
-- PD-022 refined rule: k also protects the quantitative subset.
--   eligible=3, scored=3 => SUPPRESSED (not qualitative)   [cycle 401]
--   eligible=4, scored=0 => QUALITATIVE                     [cycle 404, above]
--   eligible=4, scored=1 => SUPPRESSED (not qualitative)    [cycle 409]
--   eligible=4, scored=2 => SUPPRESSED (not qualitative)    [cycle 40a]
--   eligible=4, scored=3 => SUPPRESSED (not qualitative)    [cycle 40b]
--   eligible=4, scored=4 => QUANTITATIVE                    [cycle 402, above]
--   eligible=5, scored=4 => QUANTITATIVE                    [cycle 40c]
-- and none of the suppressed cases may leak that 1/2/3 scores exist.
-- ---------------------------------------------------------------------------
select set_config('request.jwt.claims', '{"sub":"c3000000-0000-4000-8000-000000000001","role":"authenticated"}', true);
-- eligible=3, scored=3 → suppressed and NOT qualitative.
select is(
  (select is_qualitative from public.get_tenant_person_direct_report_aggregate_v1('c3000000-0000-4000-8000-000000000101','c3000000-0000-4000-8000-000000000205') where cycle_id = 'c3000000-0000-4000-8000-000000000401'),
  false, 'eligible=3 scored=3: suppressed cohort is never labelled qualitative');
-- eligible=4, scored in {1,2,3}: SUPPRESSED, aggregate null, NOT qualitative.
select is(
  (select suppressed from public.get_tenant_person_direct_report_aggregate_v1('c3000000-0000-4000-8000-000000000101','c3000000-0000-4000-8000-000000000205') where cycle_id = 'c3000000-0000-4000-8000-000000000409'),
  true, 'eligible=4 scored=1: quantitative subset < k → suppressed');
select is(
