     from public.get_tenant_person_direct_report_aggregate_v1('c3000000-0000-4000-8000-000000000101','c3000000-0000-4000-8000-000000000205') where cycle_id = 'c3000000-0000-4000-8000-000000000401'),
  (select row(suppressed, is_qualitative, aggregate_score)::text
     from public.get_tenant_person_direct_report_aggregate_v1('c3000000-0000-4000-8000-000000000101','c3000000-0000-4000-8000-000000000205') where cycle_id = 'c3000000-0000-4000-8000-000000000409'),
  'suppressed-by-eligible and suppressed-by-scored are indistinguishable to callers');

-- admin and hr allowed.
select set_config('request.jwt.claims', '{"sub":"c3000000-0000-4000-8000-000000000002","role":"authenticated"}', true);
select lives_ok($$select * from public.get_tenant_person_direct_report_aggregate_v1('c3000000-0000-4000-8000-000000000101','c3000000-0000-4000-8000-000000000205')$$, 'same-tenant admin is allowed');
select set_config('request.jwt.claims', '{"sub":"c3000000-0000-4000-8000-000000000003","role":"authenticated"}', true);
select lives_ok($$select * from public.get_tenant_person_direct_report_aggregate_v1('c3000000-0000-4000-8000-000000000101','c3000000-0000-4000-8000-000000000205')$$, 'same-tenant HR is allowed');
-- manager and employee denied (no individual/aggregate access).
select set_config('request.jwt.claims', '{"sub":"c3000000-0000-4000-8000-000000000004","role":"authenticated"}', true);
select throws_ok($$select * from public.get_tenant_person_direct_report_aggregate_v1('c3000000-0000-4000-8000-000000000101','c3000000-0000-4000-8000-000000000205')$$, '42501', 'ASSESSMENT_DIRECT_REPORT_AGGREGATE_FORBIDDEN', 'manager denied');
