-- foreign Person and nonexistent Person: identical safe denial (no existence oracle).
select set_config('request.jwt.claims', '{"sub":"c3000000-0000-4000-8000-000000000001","role":"authenticated"}', true);
select throws_ok($$select * from public.get_tenant_person_direct_report_aggregate_v1('c3000000-0000-4000-8000-000000000101','c3000000-0000-4000-8000-000000000208')$$, '42501', 'ASSESSMENT_DIRECT_REPORT_AGGREGATE_FORBIDDEN', 'foreign Person denied without oracle');
select throws_ok($$select * from public.get_tenant_person_direct_report_aggregate_v1('c3000000-0000-4000-8000-000000000101','c3000000-0000-4000-8000-000000000999')$$, '42501', 'ASSESSMENT_DIRECT_REPORT_AGGREGATE_FORBIDDEN', 'nonexistent Person has the same safe denial');

-- anon ACL denial.
set local role anon;
select set_config('request.jwt.claims', '{"role":"anon"}', true);
select throws_ok($$select * from public.get_tenant_person_direct_report_aggregate_v1('c3000000-0000-4000-8000-000000000101','c3000000-0000-4000-8000-000000000205')$$, '42501', 'permission denied for function get_tenant_person_direct_report_aggregate_v1', 'anon denied by ACL');
-- AUTH_REQUIRED for a null-sub authenticated context.
set local role authenticated;
select set_config('request.jwt.claims', '{"role":"authenticated"}', true);
select throws_ok($$select * from public.get_tenant_person_direct_report_aggregate_v1('c3000000-0000-4000-8000-000000000101','c3000000-0000-4000-8000-000000000205')$$, '28000', 'AUTH_REQUIRED', 'null auth context denied by explicit guard');

-- ---------------------------------------------------------------------------
-- Audit: exactly one Activity per successful aggregate read; none for denials.
-- Owner read 205 once (many statements above hit it, so count reads deliberately).
-- ---------------------------------------------------------------------------
reset role;
-- The single owner read of Person 206 (empty subject, asserted above) must have
-- emitted EXACTLY ONE administrative Activity event: one per read, never per
-- response and never more than one. Asserted purely over activity_events, keyed by
-- entity_id (mirrors the 0118 discipline) — no RPC call and no auth context, so it
-- can never leave an unprotected call after the AUTH_REQUIRED assertion above.
select is(
  (select count(*) from public.activity_events event
     where event.company_id = 'c3000000-0000-4000-8000-000000000101'
       and event.entity_type = 'person'
       and event.entity_id = 'c3000000-0000-4000-8000-000000000206'
       and event.metadata ->> 'operation' = 'read_person_direct_report_aggregate'),
  1::bigint, 'exactly one audit event per authorized read (Person 206 read once above)');

reset role;
select cmp_ok(
  (select count(*) from public.activity_events event
     where event.company_id = 'c3000000-0000-4000-8000-000000000101'
       and event.entity_type = 'person'
       and event.metadata ->> 'operation' = 'read_person_direct_report_aggregate'),
  '>=', 1::bigint,
  'authorized aggregate reads emit read_person_direct_report_aggregate Activity events');
select ok(
  not exists (
    select 1 from public.activity_events event
    where event.metadata ->> 'operation' = 'read_person_direct_report_aggregate'
      and lower(event.metadata::text) ~ 'answer|question|comment|evaluator|raw_score|respondent'
  ),
  'aggregate audit metadata carries no private/cardinality payload');

-- Definition-level guards (defence in depth, mirrors 0118 test discipline).
select matches(
  (select prosrc from pg_proc where oid = 'public.get_tenant_person_direct_report_aggregate_v1(uuid,uuid)'::regprocedure),
  'auth\.uid\(\) is null', 'aggregate boundary carries an explicit auth.uid() guard');
select matches(
  (select prosrc from pg_proc where oid = 'public.get_tenant_person_direct_report_aggregate_v1(uuid,uuid)'::regprocedure),
  'v_threshold constant integer := 4', 'threshold k=4 is fixed in the definition');

select * from finish();
rollback;
